use moloch_live_runtime::discovery_flow::{Flow,FLOW_WINDOW_MS,MAX_REMEMBERED_PRINTS};
use serde_json::{json,Value};
use std::collections::BTreeMap;
const BASE:u64=1_792_022_400_000;
fn iso(ms:u64)->String{chrono::DateTime::from_timestamp_millis((BASE+ms)as i64).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn flow()->Flow{Flow::new(&[("101".into(),"1".into()),("102".into(),"2".into()),("103".into(),"3".into())].into()).unwrap().with_tournament("cup").unwrap()}
fn trade(id:&str,market:u64,at:u64)->Value{json!({"id":id,"marketId":market.to_string(),"exchangeId":(market+100).to_string(),"sequence":1,"executedAt":iso(at),"price":0.4,"quantity":1,"tournamentId":"cup"})}
fn frame(market:u64,trades:Value,resync:bool)->Value{json!({"tournamentId":"cup","markets":[{"marketId":market.to_string(),"batch":{"delivery":{"model":"best-effort-authoritative-resync","revision":5,"previousRevision":3},"resyncRequired":resync,"trades":trades}}]})}
fn add(f:&mut Flow,market:u64,trades:Value,at:u64){f.observe("markets_batch",&frame(market,trades,true),&iso(at)).unwrap();}
#[test]fn genuine_print_in_resync_batch_without_any_book_is_read_nomination(){let mut f=flow();add(&mut f,2,json!([trade("a",2,0)]),0);assert_eq!(f.ranked(BASE).unwrap(),vec![("102".into(),1)]);}
#[test]fn count_descending_then_stable_exchange_id_and_sparse_flow(){let mut f=flow();add(&mut f,3,json!([trade("c",3,0)]),0);add(&mut f,2,json!([trade("b1",2,0),trade("b2",2,0)]),0);add(&mut f,1,json!([trade("a",1,0)]),0);assert_eq!(f.ranked(BASE).unwrap(),vec![("102".into(),2),("101".into(),1),("103".into(),1)]);}
#[test]fn repeated_ids_cannot_inflate_or_refresh_original_execution_or_first_receipt(){let mut f=flow();let original=frame(1,json!([trade("a",1,0)]),true);f.observe("markets_batch",&original,&iso(0)).unwrap();f.observe("markets_batch",&original,&iso(179999)).unwrap();assert_eq!(f.remembered_prints(),1);assert_eq!(f.ranked(BASE+FLOW_WINDOW_MS).unwrap(),vec![("101".into(),1)]);assert!(f.ranked(BASE+FLOW_WINDOW_MS+1).unwrap().is_empty());}
#[test]fn delayed_old_execution_is_not_made_recent_by_fresh_receipt(){let mut f=flow();add(&mut f,1,json!([trade("old",1,0)]),180001);assert!(f.ranked(BASE+180001).unwrap().is_empty());assert_eq!(f.remembered_prints(),1);}
#[test]fn partial_gap_and_dirty_metadata_do_not_erase_or_renew_a_real_print(){let mut f=flow();add(&mut f,1,json!([trade("a",1,0)]),0);f.observe("gap",&json!({"exchangeIds":["101"]}),&iso(100)).unwrap();f.observe("book_dirty",&json!({"marketId":"1","exchangeId":"101","sourceAt":iso(100)}),&iso(100)).unwrap();assert_eq!(f.ranked(BASE+100).unwrap(),vec![("101".into(),1)]);f.observe("book_dirty",&json!({"marketId":"1"}),&iso(180001)).unwrap();assert!(f.ranked(BASE+180001).unwrap().is_empty());}
#[test]fn reset_erases_seen_and_flow_without_reusing_receipt_clock_for_old_print(){let mut f=flow();let t=trade("a",1,0);add(&mut f,1,json!([t.clone()]),0);f.observe("stream_reset",&json!({"localBoundary":true}),&iso(100)).unwrap();assert_eq!(f.remembered_prints(),0);assert!(f.ranked(BASE+100).unwrap().is_empty());add(&mut f,1,json!([t]),180001);assert!(f.ranked(BASE+180001).unwrap().is_empty());}
#[test]fn conflicting_id_facts_clear_the_entire_frame_including_valid_prefix(){for key in ["quantity","price","executedAt","sequence","exchange"]{let mut f=flow();let original=trade("a",1,0);add(&mut f,1,json!([original.clone()]),0);let mut changed=original;match key{"quantity"=>changed["quantity"]=json!(2),"price"=>changed["price"]=json!(0.405),"executedAt"=>changed["executedAt"]=json!(iso(1)),"sequence"=>changed["sequence"]=json!(2),_=>changed["exchangeId"]=json!("102")};assert!(f.observe("markets_batch",&frame(1,json!([trade("prefix",1,1),changed]),true),&iso(1)).is_err(),"{key}");assert_eq!(f.remembered_prints(),0);assert!(f.ranked(BASE+1).unwrap().is_empty());}}
#[test]fn equivalent_numeric_scope_and_tick_representations_do_not_create_conflicts(){let mut f=flow();let t=trade("a",1,0);add(&mut f,1,json!([t.clone()]),0);let mut t=t;t["marketId"]=json!(1);t["exchangeId"]=json!(101);t["price"]=json!("0.400000");add(&mut f,1,json!([t]),1);assert_eq!(f.ranked(BASE+1).unwrap(),vec![("101".into(),1)]);}
#[test]fn invalid_fields_future_clock_and_foreign_scope_clear_previous_observations(){for case in ["foreign_market","foreign_exchange","wrong_market","quantity","id","sequence","price","executed","future","tournament","array","resync","delivery","duplicate_market"]{let mut f=flow();add(&mut f,1,json!([trade("a",1,0)]),0);let mut p=frame(2,json!([trade("b",2,1)]),true);let t=&mut p["markets"][0]["batch"]["trades"][0];match case{"foreign_market"=>p["markets"][0]["marketId"]=json!("9"),"foreign_exchange"=>t["exchangeId"]=json!("999"),"wrong_market"=>t["marketId"]=json!("1"),"quantity"=>t["quantity"]=json!(0),"id"=>t["id"]=Value::Null,"sequence"=>t["sequence"]=Value::Null,"price"=>t["price"]=json!(0.401),"executed"=>t["executedAt"]=json!("bad"),"future"=>t["executedAt"]=json!(iso(2)),"tournament"=>t["tournamentId"]=json!("foreign"),"array"=>p["markets"][0]["batch"]["trades"]=Value::Null,"resync"=>p["markets"][0]["batch"]["resyncRequired"]=json!("yes"),"delivery"=>p["markets"][0]["batch"]["delivery"]["revision"]=json!(3),_=>{let row=p["markets"][0].clone();p["markets"].as_array_mut().unwrap().push(row);}}assert!(f.observe("markets_batch",&p,&iso(1)).is_err(),"{case}");assert_eq!(f.remembered_prints(),0,"{case}");}}
#[test]fn settled_scope_is_cleared_and_cannot_be_revived_even_by_reset(){let mut f=flow();add(&mut f,1,json!([trade("a",1,0)]),0);add(&mut f,2,json!([trade("b",2,0)]),0);f.observe("market_settled",&json!({"marketId":"1","at":iso(1)}),&iso(1)).unwrap();assert_eq!(f.ranked(BASE+1).unwrap(),vec![("102".into(),1)]);f.observe("stream_reset",&json!({"localBoundary":true}),&iso(2)).unwrap();add(&mut f,1,json!([trade("new",1,3)]),3);assert!(f.ranked(BASE+3).unwrap().is_empty());}
#[test]fn settlement_in_batch_suppresses_same_batch_print_and_checks_scope(){let mut f=flow();let mut p=frame(1,json!([trade("a",1,0)]),true);p["markets"][0]["batch"]["marketSettled"]=json!([{"marketId":"1","at":iso(0)}]);f.observe("markets_batch",&p,&iso(0)).unwrap();assert!(f.ranked(BASE).unwrap().is_empty());p["markets"][0]["batch"]["marketSettled"][0]["marketId"]=json!("2");assert!(f.observe("markets_batch",&p,&iso(1)).is_err());}
#[test]fn explicit_parser_error_clear_preserves_clocks_and_tombstones(){let mut f=flow();add(&mut f,1,json!([trade("a",1,10)]),10);f.clear_observations();assert_eq!(f.remembered_prints(),0);assert!(f.observe("markets_batch",&frame(1,json!([]),true),&iso(9)).is_err());add(&mut f,1,json!([trade("new",1,11)]),11);assert_eq!(f.ranked(BASE+11).unwrap(),vec![("101".into(),1)]);assert!(f.ranked(BASE+10).is_err());}
#[test]fn no_fake_reset_or_unbounded_scope_and_invalid_event(){let mut f=flow();assert!(f.observe("stream_reset",&json!({}),&iso(0)).is_err());assert!(f.observe("arbitrary",&json!({}),&iso(0)).is_err());let mut empty=Flow::new(&BTreeMap::new()).unwrap();assert!(empty.ranked(BASE).unwrap().is_empty());assert!(Flow::new(&[("01".into(),"1".into())].into()).is_err());let oversized=(1..=4097).map(|i|(i.to_string(),i.to_string())).collect();assert!(Flow::new(&oversized).is_err());}
#[test]fn remembered_id_bound_is_exact_and_overflow_fails_clear_without_partial_count(){let mut f=flow();let prints=(0..MAX_REMEMBERED_PRINTS).map(|i|trade(&format!("t{i}"),1,0)).collect::<Vec<_>>();add(&mut f,1,json!(prints),0);assert_eq!(f.remembered_prints(),MAX_REMEMBERED_PRINTS);assert_eq!(f.ranked(BASE).unwrap(),vec![("101".into(),MAX_REMEMBERED_PRINTS as u64)]);assert!(f.observe("markets_batch",&frame(1,json!([trade("overflow",1,1)]),true),&iso(1)).is_err());assert_eq!(f.remembered_prints(),0);assert!(f.ranked(BASE+1).unwrap().is_empty());}
#[test]fn submillisecond_future_execution_is_rejected_before_rounding(){let mut f=flow();let mut t=trade("a",1,0);t["executedAt"]=json!(iso(0).replace(".000Z",".000001Z"));assert!(f.observe("markets_batch",&frame(1,json!([t]),true),&iso(0)).is_err());}

#[test]fn print_ids_are_scoped_by_exchange_without_assuming_a_global_id_namespace(){let mut f=flow();add(&mut f,1,json!([trade("same-local-id",1,0)]),0);add(&mut f,2,json!([trade("same-local-id",2,0)]),0);assert_eq!(f.remembered_prints(),2);assert_eq!(f.ranked(BASE).unwrap(),vec![("101".into(),1),("102".into(),1)]);}